    import sys
    import math

    factorial_value = sys.stdin.read().strip()
    target_factorial = int(factorial_value)

    # Binary search to find the smallest n such that n! >= target_factorial
    low, high = 0, 1
    while math.factorial(high) < target_factorial:
        low = high
        high *= 2

    # Refine the search in the interval [low, high]
    while low < high:
        mid = (low + high) // 2
        if math.factorial(mid) < target_factorial:
            low = mid + 1
        else:
            high = mid

    print(low)

